local Catalog=(function()
--!nocheck
-- Targeted read-only lookup: requested inventory UUID -> unit definition -> display data.
-- Does not require arbitrary modules, call game remotes, mutate scanned tables, or export them.
local Catalog={}
local function normal(id) return type(id)=="string" and id:lower():gsub("[{}]","") or nil end
local function first(t,keys)
    for _,key in ipairs(keys) do local v=rawget(t,key);if v~=nil then return v end end
end
local function friendly(v)
    return type(v)=="string" and #v>0 and #v<=120 and not v:find("[%c_{}]") and not v:match("^Unit #%d+$")
end
local function unitType(t,guid)
    if type(t)~="table" then return nil end
    for _,key in ipairs({"unit_id","unitId","unit_type","unitType","unit","id","modelName"}) do
        local v=rawget(t,key)
        if type(v)=="string" and #v>0 and #v<=160 and normal(v)~=guid then return v end
    end
end
Catalog.friendly=friendly
function Catalog.resolve(ids,objects,d)
    local wanted,variants,types,result={},{},{},{}
    for _,id in ipairs(ids) do
        local key=normal(id);wanted[key]=id;variants[#variants+1]={id=id,key=key}
    end
    assert(#variants<=256,"Too many unique inventory units for one catalog scan")
    local visited=0
    local function yieldIfNeeded()
        visited=visited+1
        if visited%400==0 and d.yield then d.yield() end
        if d.alive then assert(d.alive(),"Catalog scan canceled") end
    end
    local function read(def,inventoryId)
        if type(def)~="table" then return end
        local name,icon
        for _,key in ipairs({"display_name","displayName","name","Name"}) do local v=rawget(def,key);if friendly(v) then name=v;break end end
        for _,key in ipairs({"image","image_id","imageId","thumbnail","icon","portrait"}) do
            local v=rawget(def,key)
            if type(v)=="number" and v>0 and v%1==0 then v="rbxassetid://"..v end
            v=d.asset(v);if v~="" then icon=v;break end
        end
        local entry=result[inventoryId] or {}
        if name then
            entry.names=entry.names or {};entry.names[name]=true
            local count=0;for _ in pairs(entry.names) do count=count+1 end
            entry.displayName=count==1 and name or nil
        end
        if icon then
            entry.icons=entry.icons or {};entry.icons[icon]=true
            local count=0;for _ in pairs(entry.icons) do count=count+1 end
            entry.icon=count==1 and icon or nil
        end
        local model=first(def,{"model","Model","unit_model"})
        if model and d.isModel and d.isModel(model) then entry.model=model end
        result[inventoryId]=entry
    end
    -- Inventory objects can expose UUID fields or live in a UUID-keyed dictionary.
    for _,t in ipairs(objects) do
        yieldIfNeeded()
        if type(t)=="table" and not (d.ignore and d.ignore[t]) then
            local guid=normal(first(t,{"uuid","unit_uuid","unitUuid","inventory_id","UUID"}))
            if guid and wanted[guid] then
                local id=wanted[guid];types[id]=unitType(t,guid) or types[id];read(t,id)
            end
            for _,v in ipairs(variants) do
                local owned=rawget(t,v.id) or rawget(t,v.key) or rawget(t,"{"..v.key.."}")
                if type(owned)=="table" then types[v.id]=unitType(owned,v.key) or types[v.id];read(owned,v.id) end
            end
        end
    end
    -- Definitions commonly expose an id or are stored under the unit type key.
    for _,t in ipairs(objects) do
        yieldIfNeeded()
        if type(t)=="table" and not (d.ignore and d.ignore[t]) then
            local ownType=first(t,{"id","unit_id","unitId"})
            for id,key in pairs(types) do
                if ownType==key then read(t,id) end
                read(rawget(t,key),id)
            end
        end
    end
    for id,key in pairs(types) do
        result[id]=result[id] or {};result[id].modelName=key
        if not result[id].model and d.findModel then result[id].model=d.findModel(key) end
    end
    return result
end

return Catalog
end)()
local Portrait=(function()
--!nocheck
-- Portable static UI portrait data. Never executes imported strings or game modules.
local Portrait={}
local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
local function array(t,n)
    if type(t)~="table" or #t~=n then return false end
    for k,v in pairs(t) do if type(k)~="number" or k<1 or k>n or k%1~=0 or not finite(v) then return false end end
    return true
end
function Portrait.clone(model)
    local changed={};local clone
    local ok,err=pcall(function()
        local objects={model};for _,v in ipairs(model:GetDescendants()) do objects[#objects+1]=v end
        for _,v in ipairs(objects) do if not v.Archivable then changed[#changed+1]=v;v.Archivable=true end end
        clone=model:Clone();assert(clone,"Clone unavailable")
    end)
    for _,v in ipairs(changed) do pcall(function() v.Archivable=false end) end
    if not ok then error(err,0) end
    for _,v in ipairs(clone:GetDescendants()) do
        if v:IsA("Script") or v:IsA("LocalScript") or v:IsA("ModuleScript") then v:Destroy()
        elseif v:IsA("BasePart") then v.Anchored=true;v.CanCollide=false;v.LocalTransparencyModifier=0 end
    end
    return clone
end
function Portrait.renderModel(viewport,prototype)
    for _,v in ipairs(viewport:GetChildren()) do v:Destroy() end
    local world=Instance.new("WorldModel");world.Parent=viewport
    local clone=Portrait.clone(prototype);clone.Parent=world
    local root=clone:GetPivot().Position
    local minimum,maximum
    for _,part in ipairs(clone:GetDescendants()) do
        if part:IsA("BasePart") and part.Transparency<0.98 and part.Size.Magnitude<200 and (part.Position-root).Magnitude<200 then
            for x=-1,1,2 do for y=-1,1,2 do for z=-1,1,2 do
                local p=part.CFrame:PointToWorldSpace(Vector3.new(part.Size.X*x/2,part.Size.Y*y/2,part.Size.Z*z/2))
                minimum=minimum and Vector3.new(math.min(minimum.X,p.X),math.min(minimum.Y,p.Y),math.min(minimum.Z,p.Z)) or p
                maximum=maximum and Vector3.new(math.max(maximum.X,p.X),math.max(maximum.Y,p.Y),math.max(maximum.Z,p.Z)) or p
            end end end
        end
    end
    assert(minimum,"No visible portrait geometry")
    local center=(minimum+maximum)/2;local size=maximum-minimum
    local distance=math.max(size.X,size.Y,size.Z,1)*2.2
    local camera=Instance.new("Camera");camera.FieldOfView=35
    camera.CFrame=CFrame.lookAt(center+Vector3.new(distance*0.45,distance*0.2,distance),center)
    camera.Parent=viewport;viewport.CurrentCamera=camera
    viewport.Ambient=Color3.new(1,1,1);viewport.LightColor=Color3.new(1,1,1);viewport.ImageTransparency=0;viewport.Visible=true
    return true
end
local function asset(value)
    if type(value)~="string" or #value>240 then return "" end
    if value:match("^rbxassetid://%d+$") or value:match("^rbxasset://[%w%p]+$") then return value end
    local id=value:match("[?&]id=(%d+)")
    return id and ("rbxassetid://"..id) or ""
end
Portrait.asset=asset
function Portrait.validate(data,validateCF)
    if data==nil then return nil end
    assert(type(data)=="table" and data.version==1 and type(data.parts)=="table","Invalid portrait")
    local count=0;for k in pairs(data.parts) do assert(type(k)=="number" and k>=1 and k%1==0,"Invalid portrait array");count=count+1 end
    assert(count>0 and count<=64 and count==#data.parts,"Invalid portrait part count")
    local clean={version=1,parts={}}
    for i=1,count do
        local p=data.parts[i];assert(type(p)=="table" and array(p.size,3) and array(p.color,3),"Invalid portrait part")
        validateCF(p.cf)
        for j=1,3 do assert(math.abs(p.cf[j])<=200,"Portrait outside local bounds") end
        for j=1,3 do assert(p.size[j]>0 and p.size[j]<=200 and p.color[j]>=0 and p.color[j]<=1,"Invalid portrait dimensions/color") end
        assert(finite(p.transparency) and p.transparency>=0 and p.transparency<=1,"Invalid portrait transparency")
        local v={size=table.clone(p.size),color=table.clone(p.color),cf=table.clone(p.cf),transparency=p.transparency}
        if p.mesh then
            assert(type(p.mesh)=="table" and array(p.mesh.scale,3),"Invalid portrait mesh")
            for _,n in ipairs(p.mesh.scale) do assert(n>0 and n<=1000,"Invalid mesh scale") end
