local function dropdown(anchor, options)
    closePopup()
    popup=n(4):Clone(); popup.Name="ActiveDropdown"; popup.Visible=true
    popup.AnchorPoint=Vector2.new(0,0)
    local origin=n(1).AbsolutePosition
    local camera=workspace.CurrentCamera
    local viewport=camera and camera.ViewportSize or Vector2.new(1024,768)
    local x=math.clamp(anchor.AbsolutePosition.X-origin.X,8,math.max(8,viewport.X-228))
    local y=math.clamp(anchor.AbsolutePosition.Y+anchor.AbsoluteSize.Y-origin.Y,8,math.max(8,viewport.Y-274))
    popup.Position=UDim2.fromOffset(x,y); popup.Size=UDim2.fromOffset(220,262); popup.Parent=gui
    for _,v in ipairs(popup:GetDescendants()) do
        if v:IsA("GuiObject") then v.ZIndex=110 end
        if v:IsA("UIScale") then v.Scale=1 end
    end
    popup.ZIndex=109
    local box=popup:FindFirstChildWhichIsA("TextBox",true)
    local scroll=popup:FindFirstChildWhichIsA("ScrollingFrame",true)
    local template=scroll:FindFirstChildWhichIsA("TextButton")
    template.Visible=false; box.Text=""; box.PlaceholderText=text("Search...", "Поиск...")
    local rows={}
    for i,option in ipairs(options) do
        local row=template:Clone(); row.Name="Option"..i; row.LayoutOrder=i; row.Visible=true
        local label=row:FindFirstChildWhichIsA("TextLabel")
        label.Text=option.label
        label.TextColor3=option.selected and n(15).TextColor3 or Color3.fromRGB(242,242,250)
        local check=row:FindFirstChildWhichIsA("ImageLabel")
        if check then check.Visible=option.selected==true end
        row.BackgroundTransparency=option.selected and 0 or 1
        row.Parent=scroll; table.insert(rows,{row=row,label=option.label})
        connect(row.Activated,safe(function() closePopup(); option.run() end),popupConnections)
    end
    if #options==0 then
