local function guiMetadata(model,id)
    local root=player:FindFirstChild("PlayerGui")
    if not root then return end
    local scanned=0
    for _,marker in ipairs(root:GetDescendants()) do
        scanned=scanned+1;if scanned>6000 then break end
        if not marker:GetFullName():find("GH_AA",1,true) then
            local linked=false
            if marker:IsA("StringValue") then linked=marker.Value==id
            elseif marker:IsA("ObjectValue") then linked=marker.Value==model end
            if not linked then
                for key,value in pairs(marker:GetAttributes()) do
                    if type(value)=="string" and value==id then linked=true;break end
                end
            end
            if linked then
                local parent=marker.Parent
                for depth=1,4 do
                    if not parent or parent==root then break end
                    local name,icon;local names,icons={},{}
                    for _,obj in ipairs(parent:GetDescendants()) do
                        local lower=obj.Name:lower()
                        if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and (lower=="name" or lower=="unitname" or lower=="displayname") and displayString(obj.Text) then names[obj.Text]=true end
                        if (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) and (lower=="unitimage" or lower=="portrait" or lower=="icon") then local value=Portrait.asset(obj.Image);if value~="" then icons[value]=true end end
                    end
                    local nameCount,iconCount=0,0
                    for value in pairs(names) do name=value;nameCount=nameCount+1 end
                    for value in pairs(icons) do icon=value;iconCount=iconCount+1 end
                    if nameCount>1 then return end
                    if iconCount>1 then icon=nil end
