local function seek(entry,before,claimed,alive,done)
    task.spawn(function()
        local deadline=os.clock()+6
        local unit,status
        repeat
            if not runtime.alive or not alive() then return end
            unit,status=Plan.candidate(entry,models(),before,claimed,position,function(u)
                local meta=core.unitCatalog[entry.id]
                return not meta or not meta.modelName or u.Name==meta.modelName
            end)
            if unit then done(unit);return end
            task.wait(0.1)
        until os.clock()>=deadline
        if alive() then report("Placement model not bound: "..tostring(status)..". Upgrades stay off for this placement.") end
    end)
end
