runtime.resolveCatalog=function()
    local source=core.entries
    if #source==0 or catalogWorking then return end
    if source==catalogSource and #source==catalogCount and os.clock()<(catalogRetry or 0) then return end
    catalogSource=source;catalogCount=#source;catalogRetry=os.clock()+20
    local ids,seen={},{}
    local needed=false
    for _,entry in ipairs(source) do
        if not seen[entry.id] then ids[#ids+1]=entry.id;seen[entry.id]=true end
        local meta=core.unitCatalog[entry.id]
        local hasIcon=meta and type(meta.icon)=="string" and meta.icon~=""
        if not meta or not Catalog.friendly(meta.displayName) or (not hasIcon and not meta.portrait and not runtime.portraitModels[entry.id]) then needed=true end
    end
    if not needed then runtime.catalogInfo="ready";runtime.catalogState="ready";return end
    if type(getgc)~="function" then runtime.catalogState="unavailable";runtime.catalogInfo="Game catalog reader unavailable in this executor. INFO contains this status.";return end
    catalogWorking=true;runtime.catalogState="reading";runtime.catalogInfo="reading game unit catalog"
    task.spawn(function()
        local ok,err=pcall(function()
            local all=getgc(true)
            assert(type(all)=="table","getgc returned no object list")
            local data={}
            for _,value in ipairs(all) do if type(value)=="table" then data[#data+1]=value end end
            local modelIndex
            local function findModel(key)
                if not modelIndex then
                    modelIndex={}
                    local count=0
                    for _,obj in ipairs(RS:GetDescendants()) do
                        count=count+1
                        if obj:IsA("Model") then
                            if modelIndex[obj.Name]~=nil then modelIndex[obj.Name]=false else modelIndex[obj.Name]=obj end
                        end
                        if count%400==0 then task.wait() end
                    end
                end
                return modelIndex[key] or nil
            end
            local ignore={[core.unitCatalog]=true,[core.entries]=true}
            for _,meta in pairs(core.unitCatalog) do ignore[meta]=true end
            local resolved=Catalog.resolve(ids,data,{asset=Portrait.asset,ignore=ignore,
                alive=function() return runtime.alive and core.entries==source end,
                yield=function() task.wait() end,
                isModel=function(value) return typeof(value)=="Instance" and value:IsA("Model") end,
                findModel=findModel,
            })
            if not runtime.alive or core.entries~=source then return end
            local ready,changed=0,false
            for id,value in pairs(resolved) do
                local previous=core.unitCatalog[id] or {};local meta={}
                for k,v in pairs(previous) do meta[k]=v end
                if value.displayName and (not meta.customName or not Catalog.friendly(meta.displayName)) then meta.displayName=value.displayName end
                if value.icon then meta.icon=value.icon end
                if value.modelName then meta.modelName=value.modelName end
                if value.model then
                    if not runtime.portraitModels[id] then
                        local cloned,model=pcall(Portrait.clone,value.model)
                        if cloned then runtime.portraitModels[id]=model end
                    end
                    if not meta.portrait then
                        local captured,portrait=pcall(Portrait.capture,value.model)
                        if captured and portrait then
                            local valid,clean=pcall(Portrait.validate,portrait,Recorder.validateCFrame)
                            if valid then meta.portrait=clean end
                        end
                    end
                end
                core.unitCatalog[id]=meta
                if meta.displayName~=previous.displayName or meta.icon~=previous.icon or meta.modelName~=previous.modelName or meta.portrait~=previous.portrait then changed=true end
                if meta.displayName and ((meta.icon and meta.icon~="") or meta.portrait or runtime.portraitModels[id]) then ready=ready+1 end
            end
            if changed then core.dirty=true end
            runtime.catalogState=ready==#ids and "ready" or "partial"
            runtime.catalogInfo="Catalog: "..ready.."/"..#ids.." units resolved. Unresolved cards are not replaced with placeholders."
        end)
        catalogWorking=false
        if not ok and runtime.alive then runtime.catalogState="unavailable";runtime.catalogInfo=tostring(err):sub(1,180) end
    end)
end

